#!/usr/bin/env python3
"""Freeze reviewed file-only contract with explicit, non-attested GUI prerequisites."""
import hashlib,json,pathlib
ROOT=pathlib.Path.cwd();R=ROOT/'09-reports/installer-ri3/recovery-pair'
m=json.loads((R/'pair-build-ziptrust.json').read_text());tests=json.loads((R/'pair-tests-ziptrust.json').read_text());v=json.loads((R/'pair-verification-ziptrust.json').read_text());a=json.loads((R/'aosp-avb-verification-ziptrust.json').read_text());gui=json.loads((R/'gui-controls.json').read_text());cert=json.loads((R/'zip-certificate.json').read_text())
assert tests['passed'] and tests['tests_run']==35 and v['passed'] and all(a['results'].values())
for n,r in m['files'].items():
 p=ROOT/r['path'];assert p.stat().st_size==r['size']
 with p.open('rb') as f:assert hashlib.file_digest(f,'sha256').hexdigest()==r['sha256']
record={'contract':'RI3_PAIRED_RECOVERY_DECLARED_GUI_V1','status':'offline_files_validated_conditional_gui_setup','files':m['files'],'public_zip_certificate':cert['added_certificate'],'runtime_pins':{'/system/bin/recovery':'b9416f70f6403ffe6cadc51626515f49f66a9961bbb7ef14898fdd9173c44a49','/system/etc/twrp.flags':'817aa5693a415a111bb80e34efcfcc672fcc62cb83e17bd61880809f36d44421','/system/etc/security/otacerts.zip':cert['candidate_store_sha256'],**{'/'+n:r['sha256'] for n,r in m['hooks'].items()}},'required_absent_paths':['/sbin/afterromflash.sh','/system/bin/afterromflash.sh'],'gui_setup':{'fresh_boot_into_exact_paired_recovery_required':True,'theme':'stock paired theme; custom themes unsupported','ordinary_install_page':'flash_confirm','install_resource':'/twres/pages/install.xml','queue_count':1,'signature':{'variable':'tw_signed_zip_verify','value':1,'label':'ZIP signature verification','page':'flash_confirm'},'automatic_reflash':{'variable':'tw_auto_reflashtwrp','value':0,'label':'Reflash OrangeFox after flashing a ROM','page':'ext_general','resource':'/twres/pages/settings.xml','if_control_unavailable':'Stop; do not infer the option is off.'},'settings_independently_attested':False,'wrong_signature_setting':'Recovery may execute an unverified updater before its native checks; native whole-ZIP verification does not replace the outer signature-enabled setup.','wrong_reflash_setting':'Outer checksum mismatch or partial read anomaly can trigger unguarded recovery reflashing and invalidate reviewed recovery/AVB state.'},'unsupported_routes':['custom themes','fox_modules_confirm','Aroma or built-in add-on paths','multiple queued ZIPs','sideload','CLI/ORS installation'],'native_requirements':['Verify entire ZIP signature with the dedicated public certificate before native partition writes.','Pin running recovery executable, hook bytes, trust store and configuration; check required absent paths.','Verify whole physical recovery_a against the exact paired image before writes; keep it byte-identical and never write recovery_b.','Retain all device/target, mount/holder, snapshot/metadata, capacity, payload hash and readback safeguards.'],'in_install_getval_guard':'Do not use: exact ORS server rejects commands while GUI flash has tw_busy=1. This is replaced by explicit source-backed setup requirements, not falsely described as runtime attestation.','avb':{'root_algorithm':'SHA256_RSA4096','recovery_algorithm':'SHA256_RSA2048','flags':0,'root_rollback':0,'recovery_rollback':1,'recovery_child_location':1,'all_other_descriptors_preserved':True},'validation':{'final_pair_readback':True,'aosp_signature_verification':True,'tests_passed':35,'lifecycle_models_only':True,'host_authored_hook_execution':True,'device_execution':False},'private_keys_in_public_outputs':False,'unconditional_installation_readiness_claimed':False,'supersedes_gui_getter_requirements_in':['pair-build.json','pair-build-ziptrust.json','RECOVERY-VARIANT-CONTRACT.md','ZIP-TRUST-CONTRACT.md']}
b=(json.dumps(record,indent=2,sort_keys=True)+'\n').encode();(R/'FROZEN-CONTRACT.json').write_bytes(b);digest=hashlib.sha256(b).hexdigest();(R/'FROZEN-CONTRACT.sha256').write_text(digest+'  FROZEN-CONTRACT.json\n')
(R/'readiness.json').write_text(json.dumps({'status':record['status'],'frozen_contract_sha256':digest,'gui_settings_independently_attested':False,'gui_setup_required':True,'device_tested':False,'unconditional_installation_readiness_claimed':False},indent=2)+'\n')
print(json.dumps({'contract_sha256':digest,'contract_bytes':len(b),'files':m['files'],'tests_passed':35,'exact_gui_controls':gui},indent=2))
